	@Test
	void aCachedSampleThatAppearsIsDetected(@TempDir Path directory) throws Exception {
		// No planning-time sampling, background sampling on: the planning finds no sample and votes for one.
		try (Fixture fixture = new Fixture(directory, false, 0, true)) {
			LmdbPlanningReadLog.Log log = fixture.plan(SAMPLED);
			LmdbPlanningReadLog.Read sample = null;
			for (LmdbPlanningReadLog.Read read : log.reads()) {
				if (read.kind() == LmdbPlanningReadLog.SAMPLE) {
					sample = read;
				}
			}
			assertTrue(sample != null && !sample.present(), "COVERAGE_PREREQUISITE: the planning found no sample");

			fixture.runtime.filters().runBackgroundSamplingCycle(10_000L);
			PatternFilterSampleEstimate cached = fixture.runtime.filters()
					.peekCachedSample((PatternKey) sample.first(), (String) sample.second());
			assertTrue(cached.passRatio() >= 0.0d, "COVERAGE_PREREQUISITE: the background sampler cached a sample");

			LmdbPlanningReadLog.ReplayResult result = log.replay(fixture.runtime,
					LmdbPlanningReadLog.configuredTolerance());
			assertEquals(LmdbPlanningReadLog.Verdict.CHANGED, result.verdict(), result.toString());
			assertEquals(LmdbPlanningReadLog.SAMPLE, result.kind(), result.toString());
		}
	}

