	// ---------------------------------------------------------------- completeness (spec test 4)

	@Test
	void aHeuristicFilterPassCacheHitCarriesTheReadsOfItsComputation(@TempDir Path directory) throws Exception {
		try (Fixture fixture = new Fixture(directory, false)) {
			LmdbHeuristicFilterPassCache cache = fixture.runtime.frontierSettings().heuristicFilterPassCache();
			LmdbPlanningReadLog.Log first = fixture.plan(FILTER);
			long hits = cache.hits();
			LmdbPlanningReadLog.Log second = fixture.plan(FILTER_REORDERED);

			assertAll(
					() -> assertTrue(cache.hits() > hits,
							"COVERAGE_PREREQUISITE: the second planning, at the same revision, hit the cache"),
					() -> assertTrue(second.complete(), second.incompleteReason()),
					() -> assertEquals(filterReads(first), filterReads(second),
							"the second planning replays the same reads as the first"));
		}
	}

	/**
	 * R12 (the reviewer's fixture for the R5 engine site): with live sampling off the learned state is stable within
	 * the planning, so the filter-pass computation reads semantic estimates the scope cache made before its slice
	 * opened; each retained slice must still carry the reads those estimates made (here the legacy guard).
	 */
	@Test
	void everyCompleteRetainedFilterPassSliceCarriesTheReadsOfTheEstimatesItUsed(@TempDir Path directory)
			throws Exception {
		try (Fixture fixture = new Fixture(directory, false)) {
			LmdbPlanningReadLog.Log log = fixture.plan(TWO_FILTERS);
			List<LmdbPlanningReadLog.Log> slices = fixture.runtime.frontierSettings()
					.heuristicFilterPassCache()
					.retainedReadsForTest();
			List<String> missing = new ArrayList<>();
			int complete = 0;
			for (LmdbPlanningReadLog.Log slice : slices) {
				if (slice.complete()) {
					complete++;
					if (slice.count(LmdbPlanningReadLog.LEGACY_GUARD) == 0) {
						missing.add(slice.readCount() + " reads");
					}
				}
			}
			int completeSlices = complete;
			assertAll(
					() -> assertTrue(log.count(LmdbPlanningReadLog.LEGACY_GUARD) > 0,
							"COVERAGE_PREREQUISITE: the planning reads the legacy state"),
					() -> assertTrue(completeSlices > 0, "COVERAGE_PREREQUISITE: complete retained slices"),
					() -> assertEquals(List.of(), missing, "complete retained slices without their legacy guard"));
		}
	}

	/**
	 * R10: a zero-hit draw that subsampled its rows at random answers "none" at random, so the next planning may sample
	 * a value: the log is incomplete. A "none" no random draw produced stays replayable.
	 */
	@Test
	void aNoneSampleFromARandomDrawLeavesThePlanningLogIncomplete(@TempDir Path directory) throws Exception {
		String previous = System.setProperty(LmdbFilterSelectivityStats.FILTER_SAMPLING_MODE_PROPERTY, "prefix");
		try {
			LmdbPlanningReadLog.Log randomised;
			long randomisedAttempts;
			try (Fixture fixture = new Fixture(directory.resolve("full-budget"), true, 0, false, -1L, 0)) {
				randomised = fixture.plan(NO_HIT);
				randomisedAttempts = fixture.runtime.filters().foregroundSampleAttempts();
			}
			LmdbPlanningReadLog.Log deterministic;
			long deterministicAttempts;
			try (Fixture fixture = new Fixture(directory.resolve("small-budget"), true, 0, false, -1L, 100)) {
				deterministic = fixture.plan(NO_HIT);
				deterministicAttempts = fixture.runtime.filters().foregroundSampleAttempts();
			}
			long fullBudgetAttempts = randomisedAttempts;
			long smallBudgetAttempts = deterministicAttempts;
			assertAll(
					() -> assertTrue(fullBudgetAttempts > 0L, "COVERAGE_PREREQUISITE: the planning sampled live"),
					() -> assertTrue(smallBudgetAttempts > 0L, "COVERAGE_PREREQUISITE: the planning sampled live"),
					() -> assertEquals("randomised-none-sample", randomised.incompleteReason(),
							"more rows than the reservoir holds, no hit: a random none"),
					() -> assertTrue(deterministic.complete(),
							"a budget the reservoir holds whole draws no random rows: "
									+ deterministic.incompleteReason()));
		} finally {
			if (previous == null) {
				System.clearProperty(LmdbFilterSelectivityStats.FILTER_SAMPLING_MODE_PROPERTY);
			} else {
				System.setProperty(LmdbFilterSelectivityStats.FILTER_SAMPLING_MODE_PROPERTY, previous);
			}
		}
	}

